script: main.loom
workflow: LeadScoringRecommendations
cases:
  - name: "MainWarmLeadRoute"
    input: { lead_description_text: "The prospect is comparing options and requested a product walkthrough next week." }
    models:
      LeadScorer: { temperature: "WARM", confidence: 0.86, ambiguous: "NO", next_step: "Schedule the requested walkthrough." }
    expect:
      result: { contains: "WARM" }
      calls: { LeadScorer: 1 }
      effects: none
      final: completed

  - name: "HotLeadBranch"
    input: { lead_description_text: "The prospect has budget approved, needs a solution this month, and asked for a purchase proposal." }
    models:
      LeadScorer: { temperature: "HOT", confidence: 0.94, ambiguous: "NO", next_step: "Prepare the requested proposal promptly." }
    expect:
      result: { contains: "HOT" }
      calls: { LeadScorer: 1 }
      effects: none
      final: completed

  - name: "ColdLeadBranch"
    input: { lead_description_text: "The contact said there is no current project or purchase timeline." }
    models:
      LeadScorer: { temperature: "COLD", confidence: 0.89, ambiguous: "NO", next_step: "Offer a low-pressure follow-up only if appropriate." }
    expect:
      result: { contains: "COLD" }
      calls: { LeadScorer: 1 }
      effects: none
      final: completed

  - name: "LowConfidenceReviewBranch"
    input: { lead_description_text: "The description only says the prospect might be interested someday." }
    models:
      LeadScorer: { temperature: "WARM", confidence: 0.42, ambiguous: "NO", next_step: "Ask the sales rep to clarify interest and timing." }
    humans: ["Review: clarify interest and timing before assigning a temperature."]
    expect:
      result: { contains: "HUMAN_REVIEW" }
      calls: { LeadScorer: 1 }
      asked: ["low-confidence"]
      effects: none
      final: completed

  - name: "AmbiguousReviewBranch"
    input: { lead_description_text: "The description gives conflicting signals about whether the prospect has an active project." }
    models:
      LeadScorer: { temperature: "WARM", confidence: 0.82, ambiguous: "YES", next_step: "Ask the sales rep to resolve the conflicting signals." }
    humans: ["Review: contact the account owner to clarify the active project."]
    expect:
      result: { contains: "HUMAN_REVIEW" }
      calls: { LeadScorer: 1 }
      asked: ["ambiguous"]
      effects: none
      final: completed

  - name: "InvalidStructuredAnswer"
    input: { lead_description_text: "The prospect requested pricing and has a confirmed buying timeline." }
    models:
      LeadScorer:
        - { temperature: "BOILING", confidence: 0.9, ambiguous: "NO", next_step: "Prepare pricing." }
        - { temperature: "STILL_INVALID", confidence: 0.9, ambiguous: "NO", next_step: "Prepare pricing." }
    humans: ["Review: determine the temperature and an appropriate next step."]
    expect:
      result: { contains: "HUMAN_REVIEW" }
      calls: { LeadScorer: 2 }
      asked: ["could not produce a valid result"]
      effects: none
      final: completed

  - name: "TokenBudgetLimit"
    input: { lead_description_text: "The prospect requested more information." }
    fail: { LeadScorer: { always: true, category: quota } }
    humans: ["Review: determine the temperature and an appropriate next step."]
    expect:
      result: { contains: "HUMAN_REVIEW" }
      calls: { LeadScorer: 1 }
      asked: ["could not produce a valid result"]
      effects: none
      final: completed

  - name: "CallBudgetLimit"
    input: { lead_description_text: "The prospect requested more information." }
    fail: { LeadScorer: { always: true, category: quota } }
